async function branchRow(db,cafeSlug,branchSlug){return db.prepare("SELECT b.id,b.cafe_id,b.name,b.city,b.address,b.active,b.space_mode FROM branches b JOIN cafes c ON c.id=b.cafe_id WHERE c.slug=? AND b.slug=? AND b.active=1 LIMIT 1").bind(cafeSlug,branchSlug).first()}

async function readSetup(db){
  const cafe=await db.prepare("SELECT id,slug,name,created_at FROM cafes WHERE slug!='roma' ORDER BY created_at DESC LIMIT 1").first();
  if(!cafe)return {configured:false};
  const result=await db.prepare("SELECT id,slug,name,city,address,active FROM branches WHERE cafe_id=? ORDER BY updated_at,id").bind(cafe.id).all(),branches=result.results||[];
  return {configured:true,cafe:{slug:cafe.slug,name:cafe.name,structure:branches.length>1||cafe.slug.startsWith("multi-")?"multi":"single"},branches:branches.map(branch=>({id:branch.id,slug:branch.slug,name:branch.name,city:branch.city,address:branch.address,active:Boolean(branch.active)}))};
}
async function writeSetup(db,body,editing=false){
  const name=String(body.cafeName||"").trim().slice(0,80),city=String(body.city||"").trim().slice(0,60),branchName=String(body.branchName||"").trim().slice(0,80),address=String(body.address||"").trim().slice(0,180),structure=body.structure==="multi"?"multi":"single";
  if(name.length<2||city.length<2||branchName.length<2)return reply({error:"invalid_setup",message:"Enter the café, city, and branch names."},400);
  if(editing){
    const current=await readSetup(db);if(!current.configured)return reply({error:"setup_not_found"},404);
    const cafeId=`cafe:${current.cafe.slug}`,branch=current.branches.find(item=>item.slug===body.branchSlug)||current.branches[0];
    await db.batch([db.prepare("UPDATE cafes SET name=? WHERE id=?").bind(name,cafeId),db.prepare("UPDATE branches SET name=?,city=?,address=?,updated_at=? WHERE cafe_id=? AND slug=?").bind(branchName,city,address,new Date().toISOString(),cafeId,branch.slug)]);
    return reply(await readSetup(db));
  }
  const existing=await readSetup(db);if(existing.configured)return reply(existing);
  const token=crypto.randomUUID().replace(/-/g,"").slice(0,10),cafeSlug=`${structure==="multi"?"multi":"cafe"}-${token}`,branchSlug="main";
  await writeMap(db,cafeSlug,branchSlug,{cafeName:name,branchName,city,address,map:starterMap});
  await writeSettings(db,cafeSlug,branchSlug,{...defaultSettings,cafeName:name,branchName,city,address});
  const branch=await branchRow(db,cafeSlug,branchSlug);await writeSchedule(db,branch,{hours:defaultHours(),closures:[]});
  return reply(await readSetup(db),201);
}
async function createBranch(db,body){
  const current=await readSetup(db);if(!current.configured)return reply({error:"setup_required",message:"Set up your café first."},409);
  const name=String(body.name||"").trim().slice(0,80),city=String(body.city||"").trim().slice(0,60),address=String(body.address||"").trim().slice(0,180);
  if(name.length<2||city.length<2)return reply({error:"invalid_branch",message:"Enter a branch name and city."},400);
  const slug=`branch-${crypto.randomUUID().replace(/-/g,"").slice(0,10)}`;
  await writeMap(db,current.cafe.slug,slug,{cafeName:current.cafe.name,branchName:name,city,address,map:starterMap});
  await writeSettings(db,current.cafe.slug,slug,{...defaultSettings,cafeName:current.cafe.name,branchName:name,city,address});
  const branch=await branchRow(db,current.cafe.slug,slug);await writeSchedule(db,branch,{hours:defaultHours(),closures:[]});
  return reply(await readSetup(db),201);
}
async function updateBranch(db,slug,body){
  const current=await readSetup(db);if(!current.configured)return reply({error:"setup_required"},409);
  const branch=current.branches.find(item=>item.slug===slug);if(!branch)return reply({error:"branch_not_found",message:"Branch not found."},404);
  const name=String(body.name??branch.name).trim().slice(0,80),city=String(body.city??branch.city).trim().slice(0,60),address=String(body.address??branch.address).trim().slice(0,180),active=body.active!==false;
  if(name.length<2||city.length<2)return reply({error:"invalid_branch",message:"Enter a branch name and city."},400);
  if(!active&&branch.active&&current.branches.filter(item=>item.active).length===1)return reply({error:"last_active_branch",message:"At least one branch must stay active."},409);
  await db.prepare("UPDATE branches SET name=?,city=?,address=?,active=?,updated_at=? WHERE cafe_id=? AND slug=?").bind(name,city,address,active?1:0,new Date().toISOString(),`cafe:${current.cafe.slug}`,slug).run();
  return reply(await readSetup(db));
}
