  await env.DB.batch([env.DB.prepare("UPDATE otp_challenges SET consumed_at=? WHERE mobile=? AND consumed_at IS NULL").bind(now,mobile),env.DB.prepare("INSERT INTO otp_challenges (id,mobile,salt,code_hash,expires_at,attempts,consumed_at,created_at) VALUES (?,?,?,?,?,0,NULL,?)").bind(challengeId,mobile,salt,codeHash,expiresAt,now)]);
  return reply({challengeId,expiresIn:120,requiresBootstrap,delivery:delivery.mode,...(delivery.mode==="demo"?{demoCode:code}:{})});
