  const now=new Date().toISOString(),internalNotes=body.internalNotes??row.internal_notes??"",statements=[db.prepare("DELETE FROM reservation_locks WHERE reservation_id=?").bind(row.id),db.prepare("DELETE FROM reservation_tables WHERE reservation_id=?").bind(row.id),db.prepare("UPDATE reservations SET customer_name=?,mobile=?,party_size=?,reserved_at=?,status=?,notes=?,internal_notes=?,updated_at=? WHERE id=?").bind(name,mobile,partySize,`${date}T${time}`,status,String(body.notes??row.notes).slice(0,240),String(internalNotes).slice(0,500),now,row.id)];
  if(["cancelled","completed","no_show"].includes(status))statements.push(db.prepare("UPDATE sms_messages SET status='cancelled' WHERE reservation_id=? AND kind='reminder' AND status='queued'").bind(row.id));else statements.push(db.prepare("UPDATE sms_messages SET scheduled_at=?,mobile=?,customer_name=? WHERE reservation_id=? AND kind='reminder' AND status='queued'").bind(subtractLocalMinutes(`${date}T${time}`,settings.smsReminderMinutes),mobile,name,row.id));
